export const WORLDS=['Microgravity','Moon','Mars','Earth'];
export const COLORS={Microgravity:'#b5abd0',Moon:'#b6cfff',Mars:'#d8ae81',Earth:'#91a5be'};
export const TYPES={reported_experimental_limit_aggregate:{name:'Published limit',color:'#b6cfff'},reported_fit_to_experimental_data:{name:'Fitted result',color:'#819bd2'},reported_experimental_summary:{name:'Reported summary',color:'#a6afbd'},source_derived_from_limit_aggregates:{name:'Derived summary',color:'#b8a4cd'},model_derived_compensation_from_experiments:{name:'Model-derived',color:'#d8ae81'}};
export const MATERIALS=['Ultem 1000','Mylar G','Nomex HT90-40'];
export const number=(x,digits=1)=>x===null||x===undefined||x===''?'Not reported':Number(x).toLocaleString('en-US',{maximumFractionDigits:digits});
export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function safeUrl(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:'#'}catch{return '#'}}
export function joinResearch(bundle){const exp=new Map(bundle.experiments.map(e=>[e.experiment_id,e]));const sources=new Map(bundle.sources.map(s=>[s.source_id,s]));return bundle.measurements.map(m=>({...m,experiment:exp.get(m.experiment_id),source:sources.get(m.source_id),kind:TYPES[m.evidence_type]||{name:m.evidence_type,color:'#a6afbd'}}));}
export function getLimits(rows,material,world){const matching=rows.filter(r=>r.experiment?.material===material&&r.experiment?.gravity_label===world&&r.evidence_type==='reported_experimental_limit_aggregate');return {uloi:matching.find(r=>r.metric==='ULOI'||r.metric==='ULOI*'),moc:matching.find(r=>r.metric==='MOC'||r.metric==='MOC*')};}
export function filterRows(rows,{query='',world='All',material='All',kind='All'}={}){const terms=query.trim().toLowerCase().split(/\s+/).filter(Boolean);return rows.filter(r=>(world==='All'||r.experiment?.gravity_label===world)&&(material==='All'||r.experiment?.material===material)&&(kind==='All'||r.evidence_type===kind)&&terms.every(q=>[r.measurement_id,r.metric,r.unit,r.value,r.experiment?.material,r.experiment?.gravity_label,r.source?.title,r.source_id,r.kind.name].join(' ').toLowerCase().includes(q)));}
export function csv(rows){const fields=['measurement_id','material','gravity','metric','value','unit','evidence_type','source_url','pdf_page','limitation'];const cell=value=>{let text=String(value??'');if(/^[=+@\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'};return [fields.join(','),...rows.map(r=>[r.measurement_id,r.experiment?.material,r.experiment?.gravity_label,r.metric,r.value,r.unit,r.evidence_type,r.source?.url,r.pdf_page,r.limitation].map(cell).join(','))].join('\r\n');}
export function comparisonRows(rows,material){return WORLDS.map(world=>({world,...getLimits(rows,material,world)}));}
